async function loadOnline(kind){clearTimeout(leaderboardResetTimer);const request=++onlineRequest;modal=kind;onlineData=null;onlineError='';renderModal();try{await cloud.flushRanking();const data=await api(kind==='online-stats'?'/stats':'/leaderboard?board='+leaderboardTab);if(modal===kind&&request===onlineRequest){onlineData=data;if(kind==='online-leaderboard'&&data.nextResetAt)leaderboardResetTimer=setTimeout(()=>{if(modal===kind)loadOnline(kind);},Math.max(1000,data.nextResetAt-Date.now()+100));}}catch(e){if(request===onlineRequest)onlineError=e.message;}if(modal===kind&&request===onlineRequest)renderModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;try{
 if(a==='online-account'){reauth=false;registerMode=false;show('account');}
 if(a==='account-register-mode'||a==='account-login-mode'){registerMode=a==='account-register-mode';show('account');}
 if(a==='account-reauth'){reauth=true;registerMode=false;show('account');}
 if(a==='online-leaderboard'||a==='online-stats')await loadOnline(a);
 if(a==='leaderboard-tab'&&['status','collection','fashion'].includes(b.dataset.id)){leaderboardTab=b.dataset.id;await loadOnline('online-leaderboard');}
 if(a==='online-updates'){show('online-updates');releases.markSeen();refreshReleaseIndicators();}
 if(a==='cloud-save'){b.disabled=true;await cloud.flush();toast(cloud.info().status);renderModal();}
 if(a==='cloud-reload'){b.disabled=true;await cloud.useCloud();modal=null;render();resume(true,false);}
 if(a==='account-logout'){b.disabled=true;await cloud.logout();modal=null;page='home';render();resume(true,false);}
 }catch(err){toast(err.message);b.disabled=false;}});

