function eventPortrait(n){if(!n)return '';return `<figure class="side-portrait"><div class="side-portrait-art">${n.gender==='male'?`<img src="${E.npcPortrait(n)}" alt="${esc(displayNames(n.name))}">`:character(n.appearance,'avatar','npc-floral-portrait')}</div><figcaption><span>${esc(n.role)}</span><strong>${esc(displayNames(n.name))}</strong></figcaption></figure>`;}
function endingPartner(d){const n=s.npcs.find(n=>n.id===(d.npc||d.epilogue?.npc));return n?`<div class="ending-partner">${eventPortrait(n)}</div>`:'';}
function sideEventPanel(){const q=E.pendingSideEvent(s),n=s.npcs.find(n=>n.id===q?.npc);if(!q||!n&&!['fire','bully'].includes(q.kind))return '';let heading,text,choices;
 if(q.kind==='walk'){heading='Lời hẹn dưới hàng liễu';text=`${n.name} đến tìm nàng, muốn cùng nàng ra vườn dạo chơi và tâm sự đôi điều. Nàng có nhận lời không?`;choices=button('Nhận lời đi dạo','side-choice','primary full','data-id="accept"')+button('Khước từ lời hẹn','side-choice','subtle full','data-id="decline"');}
 else if(q.kind==='gift'){heading='Một món quà bất ngờ';text=`${n.name} gửi tới một ${q.gift==='cage'?'lồng thú kỳ duyên':q.gift==='jade'?'rương ngọc':'rương gấm'}, kèm lời hỏi thăm nàng.`;choices=button('Nhận quà · Ghi nhớ tấm lòng','side-choice','primary full','data-id="receive"');}
 else if(q.kind==='disfigurement'){heading='Linh miêu trong vườn vắng';text=lynxIntro(n);choices=button('Tiếp tục','side-choice','primary full','data-id="continue"');}
 else if(q.kind==='fire'){heading='Lửa cháy trong hậu cung';text='Tiếng kêu cứu đánh thức nàng giữa đêm. Ngọn lửa đã lan đến nơi cất y phục và trang sức.';choices=button('Kiểm tra túi đồ','side-choice','primary full','data-id="continue"');}
 else{const item=q.item?itemById(q.item):null;heading='Kẻ trên gây khó dễ';text=`${n?n.role+' '+n.name:'Một vị phi tần phẩm cấp cao'} chặn đường nàng, đòi ${item?item.name:q.silver+' bạc'}. “${n?femaleLine(s,n,'Thứ này {you} cứ giao cho {self}, đừng làm mất thời gian.'):'Thứ này cứ giao cho ta, đừng làm mất thời gian.'}”`;choices=(item?`<div class="side-demand">${itemArt(item)}<strong>${esc(item.name)}</strong></div>`:'')+button('Nhẫn nhịn · Giao '+(item?'món đồ':q.silver+' bạc'),'side-choice','primary full',`data-id="give" ${E.canYieldDemand(s,q)?'':'disabled'}`)+button('Không giao · Giữ lại của mình','side-choice','subtle full','data-id="refuse"');}
 return `${title('CHUYỆN BÊN LỀ TRONG CUNG',heading)}${q.kind==='disfigurement'&&n?.bond>50?rumorPortrait(n,character):eventPortrait(n)}<p class="story">${esc(text)}</p><div class="choices">${choices}</div>`;
}

// Update badges do not rerender an active minigame or alter a guest's save.
function refreshReleaseIndicators(){
 const unread=releases.unread(),gear=$('.header-buttons [data-action="settings"]'),entry=$('[data-action="online-updates"]');
 for(const el of [gear,entry])if(el){el.querySelector('.update-dot')?.remove();if(unread)el.insertAdjacentHTML('beforeend',updateDot);}
 gear?.setAttribute('aria-label','Menu tài khoản và cộng đồng'+(unread?' · Có cập nhật mới':''));
 entry?.setAttribute('aria-label','Thông báo cập nhật'+(unread?' · Có cập nhật mới':''));
}
let checkingRelease=false,lastReleaseCheck=0;
async function checkRelease(){
 if(location.protocol==='file:'||checkingRelease||document.hidden||Date.now()-lastReleaseCheck<60000)return;
 checkingRelease=true;lastReleaseCheck=Date.now();
 try{const response=await fetch('release.json',{cache:'no-store',credentials:'omit'});if(response.ok&&releases.accept(await response.json())){
  if(modal==='online-updates'){renderModal();releases.markSeen();}
  refreshReleaseIndicators();
 }}catch{}finally{checkingRelease=false;}
}
window.addEventListener('storage',event=>{if(event.key===RELEASE_SEEN_KEY){releases.syncSeen();refreshReleaseIndicators();}});
window.addEventListener('focus',checkRelease);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkRelease();});
setInterval(checkRelease,5*60*1000);checkRelease();
